quests[39606] = { id = 39606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasures of Deathwing", description = "Neltharion's Vault? Well why didn't that spiritwalker just say so?\n\nWhen we were jumpin' into the cavern I thought I saw a chamber up high that might have what we are after.\n\nHave a look around this place while I see if I can't find a way up.", sourceObjective = "Defend Brann Bronzebeard.", sourceObjectiveStatus = "unverified-source-field" }
