quests[39614] = { id = 39614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Out of Water", description = "The drogbar are on a rampage! They're smashing everything they can find and are throwing fish to the shore.\n\nWorst of all, it is the wrong time to harvest fish. They must be returned to the waters so they can breed.", progress = "We used to supply the drogbar with most of their food between our fish and crops. What will the fools eat now?", completion = "Thank you. You saved enough fish that they can breed a new population.", objectives = "Return 8 Whitewater Carp to the river.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
