quests[39644] = { id = 39644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Enchanting Research G/3/3/3" }
quests[39645] = { id = 39645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calibration Experts", description = "It will take the cooperation of several highly skilled sorts to calibrate these burettes.\n\nMyshalla Streambreeze in Feralas has demonstrated admirable attention to detail.\n\nI loathe Ironforge, but a resident named Krimple Proxmeasure is known for his precision.\n\nAnd while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair... mostly.", completion = "Yes, I'd say these burettes look well-calibrated.\n\nI knew those three would be meticulous. Never underestimate the value of someone who obsesses over tiny details, {name}!", objectives = "Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39646] = { id = 39646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Albino Elderhorn" }
quests[39647] = { id = 39647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Little Ones!" }
quests[39648] = { id = 39648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Are the Children?", description = "The children have gone missing!\n\nThat horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them!\n\nOur scouts have spotted him over in Frostfire Ridge.", progress = "Thank you for all the help! Their families will be so happy to see them.", completion = "Thank you for all the help! Their families will be so happy to see them.", objectives = "Save 6 Kidnapped Children.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39649] = { id = 39649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menacing Grumplings", description = "The grumplings are horrid creatures. They're the ones doin' the dirty work for Grumpus.\n\nIf you're able to remove the threat I'm sure rescuing the children won't be much of a problem.", progress = "Well that was fast! Grumpus is gonna have a hard time continuing his work without his minions.\n\nTake these. I had them specially crafted to withstand any climate.\n\nYou never know what you'll run into out here in Draenor!", completion = "Well that was fast! Grumpus is gonna have a hard time continuing his work without his minions.\n\nTake these. I had them specially crafted for ya.\n\nYou never know what you'll run into out here in Draenor!", objectives = "Kill 8 Grumplings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39651] = { id = 39651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grumpus", description = "One of Draenor's oldest stories is the legend of Grumpus.\n\nThe story tells of a mean-spirited brute that would come in the night, in the dead of winter, and kidnap children that misbehaved. Back at his lair, he would present them with awful toys, and use their tears to spawn his minions.\n\nBut Grumpus is no legend, he's real and he's taken our children! Please, you have to slay him!", completion = "Thanks, {name}. I couldn't have done it without you.\n\nTake these as a token of my appreciation.\n\nHappy holidays!", objectives = "Slay Grumpus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39652] = { id = 39652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Dragons Rule", description = "Thanks to your help, Thrymjaris was able to escape the clutches of that vile demon. She bid me wait for you, so that I could take you to her once you had finished dispatching your foes.\n\nShe has gathered our brood at the top of Thorim's Peak to prepare for a counterattack. \n\nWould you join us?", completion = "You are truly a hero to my brood.  \n\nYou have gained a powerful ally today, outsider. The God-King has reason to fear you.", objectives = "Speak to Vethir to fly to the top of Thorim's Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39654] = { id = 39654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odyn and the Valarjar", description = "Fear not, mortal, you are not dead. I was directed to collect you before your demise by Odyn himself.\n\nI will take you to Odyn now, follow me.", completion = "Now all here know who you are. It is time for armaments befitting my champion.", objectives = "Follow Danica to see Odyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39655] = { id = 39655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If At First You Fail, Try Again!", description = "Looks like that Submarine had a bit more firepower than we thought!  They used First Strike to hit us before we even saw it coming.\n\nLosing ships is a part of naval battles, Commander.  Luckily, we were prepared for this exact sort of situation.  Speak with Yanas down at the dry docks, he should be able to help us quickly produce another Destroyer.  Head back here when the ship is complete, we will have a new mission ready for you.", progress = "Get that replacement Destroyer built?", completion = "That was an amazing turn around commander!  Great work.", objectives = "Meet Yanas Seastrike at the dry docks and build another Destroyer. Once the Destroyer is complete, send it on a new mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39656] = { id = 39656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Pack Attack", description = "It's time to attack the pack! I've preloaded the hand cannon. All you have to do is point and shoot.\n\nThe critters should survive the blast and hit the ground running. The howlers will be distracted by the critters, allowing you to focus on killing the packleaders.\n\nHappy hunting!", progress = "The critter hand cannon is loaded and ready for use! Just aim for one of the packs nearby. The packleaders should be easy to kill once the howlers are distracted.", completion = "You made it back without any scratches. It looks like the backfire issue from the last prototype worked itself out.\n\nA few more tweaks and I'd say this hand cannon is ready for mass production. Thanks for the help, {name}.", objectives = "Shoot the Critter Hand Cannon near wolf packs so that they scatter, allowing the packleaders to be singled out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39657] = { id = 39657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39658] = { id = 39658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39659] = { id = 39659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39661] = { id = 39661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifespring Cavern", description = "The drogbar have taken over my cavern. It is where we Rivermane practice our water magic and get much of the purest healing water in Highmountain.\n\nMeet me there and we will cleanse that sacred place of these dark-dwellers.", completion = "Are you ready? We are about to enter a cave... and the drogbar are at home in such dark places.", objectives = "Meet Jale Rivermane at Lifespring Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39663] = { id = 39663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Felbat Wings", description = "It is time. We have dealt the Legion's forces a crippling blow from which they will never recover.\n\nQuickly, let us mount up and take the fight to Tyranna's command center.", completion = "Can you sense her power? It will take all of you combined.\n\nEven so... I better go secure our way out of here.", objectives = "Grab a felbat from Illidari Whitemoon and fly up to the Fel Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39665] = { id = 39665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Naval Commander", description = "Yes!  Those are the blueprints I misplaced when I was fishing last week.  These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships.  This should let us break the naval blocade and expand our control of the Draenor seas.", progress = "Get that equipment installed?", completion = "Equipment can really make a difference out there!", objectives = "Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39666] = { id = 39666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equipping Our Fleet", description = "Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war.  Find Salty Jorren down at the docks, he should be able to help us out.", progress = "Yes?", completion = "Equipment can really make a difference out there, let's see what I can do to help ya out.", objectives = "Meet Salty Jorren at the docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39667] = { id = 39667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Lyndras: Leyflame Larceny", description = "The guards here must have seen Lyndras come through. The trail of ley dust isn't exactly hard to miss either.\n\nPerhaps one of the guards knows what became of Lyndras.", completion = "You looking for that crazed elf? Sorry to say he's been locked up.\n\nWe found him hunched in the corner making all sorts of noise and when we approached him, he attacked one of our guards.\n\nWe also found him with an item that was reported stolen. We had no choice but to lock him up in Violet Hold.", objectives = "Ask the Violet Hold guards about Lyndras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39668] = { id = 39668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Horrible Presents!", description = "That mean old Grumpus has amassed a collection of odd gifts. He's deliberately trying to crush the spirit of children everywhere by giving out the worst presents imaginable.\n\nTake this spirit bomb. Toss it on some of Grumpus's unusual gifts and take them out for good!\n\nWe're in this together, {name}. Now go and save the spirit of the holiday!", progress = "Wow. Those were some nasty presents. You might want to, uh... wash up. Who knows what those were made of.", completion = "Wow. Those were some nasty presents. You might want to, uh... wash up. Who knows what was inside some of those packages.", objectives = "Destroy 5 Unusual Gifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39670] = { id = 39670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Critter Scatter Shot", description = "The howlers in these hills travel in packs. Three against one isn't a fight I want to pick.\n\nLuckily those wolves are no match for my engineering skills! I just put the finishing touches on the prototype of a device that will help scatter the pack. All I need now is some ammo...\n\nSnatch me some rabbits from the meadow south of here, and I'll let you be the first to try out the hand cannon.", progress = "Have you snatched the rabbits yet?", completion = "Hrm, these rabbits are a bit bigger than I thought, but we should still be able to stuff a few of them into the hand cannon.", objectives = "Catch rabbits in Sunfrost Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39671] = { id = 39671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guards and Criswold" }
quests[39674] = { id = 39674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If At First You Fail, Try Again!", description = "Looks like that Submarine had a bit more firepower than we thought!  They used First Strike to hit us before we even saw it coming.\n\nLosing ships is a part of naval battles, Commander.  Luckily, we were prepared for this exact sort of situation.  Speak with Solog down at the dry docks, he should be able to help us quickly produce another Destroyer.  Head back here when the ship is complete, we will have a new mission ready for you.", progress = "Get that replacement Destroyer built?", completion = "That was an amazing turn around commander!  Great work.", objectives = "Meet Solog Roark at the dry docks and build another Destroyer. Once the Destroyer is complete, send it on a new mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39675] = { id = 39675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equipping Our Fleet", description = "Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war.  Find Kronk Rustspark down at the docks, he should be able to help us out.", progress = "Find Kronk?", completion = "Equipment can really make a difference out there, let's see what I can do to help ya out.", objectives = "Meet Kronk Rustspark at the docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39676] = { id = 39676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Naval Commander", description = "Yes!  Those are the blueprints I misplaced when I was fishing last week.  These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships.  This should let us break the naval blockade and expand our control of the Draenor seas.", progress = "Get that equipment installed?", completion = "Equipment can really make a difference out there!", objectives = "Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39680] = { id = 39680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between the Hammer...", description = "{name}, I fear that my spirit will remain bound to this place unless I am made whole again.\n\nLong ago, I discovered a cave near the coast behind Black Rook Hold. I explored the cave only to find an abominable creature that attacked me, causing me to drop my hammer as I fled.\n\nI need that hammer back if I am to be at peace.", progress = "Any luck retrieving my hammer?", completion = "Thank you, {name}. Words cannot express what this means to me.\n\nAnd as promised, here is a gift of knowledge to you.", objectives = "Bring Saris' Hammer back to his shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39681] = { id = 39681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Properties of Leystone", description = "I've never seen anything like this \"leystone\" ore. It's light, like mithril, but it carries much more of a magical energy... more even than saronite or elementium.\n\nLet's try making something with it. How about a nice pair of gauntlets?", completion = "Are you alright? Most of my stock seems to be unharmed by the flames. It's a good thing this wasn't the tailoring shop.\n\nThe explosion seemed to happen when I applied the flux.\n\nNo flux means no welding. That's a shame. Without the ability to weld, we're limited to crafting belts and bracers.", objectives = "Observe Alard as he attempts to work with the leystone ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39682] = { id = 39682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Felbat", description = "You heard what Maiev said. We need to get out of here.\n\nThere is an elevator shaft at the far end of these caverns. Let us make our way there.", completion = "Kayn and Altruis said you would be coming. Just in time, {name}.", objectives = "Ride a felbat to the upper vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39683] = { id = 39683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged in Fire", description = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. \n\nSomehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long.\n\nThe demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining.\n\nI believe that person could be you, {name}.", completion = "Yes... just look you... surging with new power and knowledge!", objectives = "Kill Immolanth and take his power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39684] = { id = 39684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beam Me Up", description = "To the east is an intricate prison chamber designed to contain the beholder, Glazer.\n\nIt began malfunctioning shortly after the breach.\n\nYou will need to rotate the mirrors in the room to focus an energy beam onto the creature. Otherwise, we cannot break through Glazer's impenetrable shield.\n\nHurry. Altruis went ahead to assist the others, but we are losing the fight.", completion = "I had no doubt you would know what to do.", objectives = "Break Glazer's shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39685] = { id = 39685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frozen in Time", description = "The Wardens kept all kinds of dangerous monsters locked up within this Vault. Now that Gul'dan's forces have breached the walls, it's proving rather... inconvenient.\n\nMany of our forces are occupied with containing a fearsome magma destroyer in the southern chamber. With us freshly awoken from stasis, we don't have the means to take it down. However, we might be able to reactivate the room's containment field.\n\nGo join up with Kayn. Do whatever it takes to seal that chamber!", completion = "I knew you could do it, {name}. We could not let that creature escape.", objectives = "Activate the Countermeasures in the Vault of Ice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39686] = { id = 39686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All The Way Up", description = "Kor'vas went ahead to meet up with Kayn and Altruis.\n\nStep onto the elevator when it arrives, and meet them in the Hall of Judgment above.", completion = "This is serious. Their core ideals are in direct conflict.\n\nI fear they will take this duel to the death.", objectives = "Ride the elevator to the Hall of Judgment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39687] = { id = 39687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbingers of the Past", description = "{name}, you must stop this argument before the damage is irreparable.\n\nKayn and Altruis must be reminded of their common bonds.\n\nThe Pool of Judgment can reflect memories of the past. Touch it, and draw upon your own recollections. \n\nRemind them what it meant to fight under Lord Illidan. Remind them why we took the demon hunter's path.", objectives = "Gaze into the Pool of Judgment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39688] = { id = 39688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", completion = "We escaped the Vault, but our work is far from over.\n\nThe Legion's assault on this world is just beginning.\n\nIf Azeroth is to survive, we may have to work with this... Archmage Khadgar.", objectives = "Kill Bastillax and take his power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39689] = { id = 39689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari, We Are Leaving", description = "The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.\n \nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.\n\nI only ask that you come with me. Further instructions await you on the other side.", sourceObjective = "Speak to Archmage Khadgar.", completion = "If you are ready, I will take you to our destination.\n\nAre you prepared to leave?", sourceObjectiveStatus = "unverified-source-field" }
quests[39690] = { id = 39690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari, We Are Leaving", description = "The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.\n \nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.\n\nI only ask that you come with me. Further instructions await you on the other side.", sourceObjective = "Speak to Archmage Khadgar.", completion = "If you are ready, I will take you to our destination.\n\nAre you prepared to leave?", sourceObjectiveStatus = "unverified-source-field" }
quests[39691] = { id = 39691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of War", completion = "Dark times have fallen upon Stormwind, {name}.\n\nWith King Varian Wrynn slain on the Broken Shore, uncertainty and tension grip the Alliance leaders.\n\nThe timing of this tragedy is no accident. The Burning Legion seeks to sow disorder amongst its enemies, weakening its prey from within.\n\nWe must act.", objectives = "Speak to Jace Darkweaver in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39692] = { id = 39692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of War", description = "The Warchief Vol'jin is expecting you.\n\nEnter Grommash Hold straight ahead, and make your introduction.", sourceObjective = "Speak to the Warchief.", sourceObjectiveStatus = "unverified-source-field" }
quests[39693] = { id = 39693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Huln", description = "The drogbar have a tool of the titans in their possession, and it falls to us to find a way to get around that.\n\nTo that end, I recommend we walk the Path of Huln to the place our people first recovered the hammer so many generations ago.\n\nI have asked for the aid of Brann in this endeavor as there are few in the living world more acquainted with titan artifacts.\n\nThe road is dangerous, and we could use your aid upon it.", objectives = "Escort Spiritwalker Ebonhorn on the Path of Huln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39694] = { id = 39694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", completion = "We escaped the Vault, but our work is far from over.\n\nThe Legion's assault on this world is just beginning.\n\nIf Azeroth is to survive, we may have to work with this... Archmage Khadgar.", objectives = "Kill Bastillax and take his power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39695] = { id = 39695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Vantus Rune Used" }
quests[39696] = { id = 39696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Champions", objectives = "Highlord, so long as the Order of the Silver Hand stands, we will do everything in our power to destroy the Legion's foothold on Azeroth.\n\nTo succeed, we will need to enlist the best of our order.\n\nLet me be the first to serve, {name}. I will act as your eyes and blade where you are not; I will carry out your will until my dying breath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39697] = { id = 39697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master vs. Commander", description = "I've been doing a little digging - or whatever you call digging in naval terms. Snorkeling?\n\nGul'dan has sent his most powerful flagship on a scouting mission to the four corners of Draenor. He is mapping out all the oceanic ley-line conjunctions. This is information that I could use to upgrade your ring... But in Gul'dan's hands, it could be catastrophic.\n\nScramble the fleet, {name}! Hunt down his infamous flagship, \"The Master's Call,\" and steal that map before they complete their mission. Hurry!", progress = "I hope the Master's Call hasn't sent too many of your ships to the bottom of the sea...?", completion = "Yes yes, this is it. This map is invaluable. By triangulating these oceanic junction points we can graph out Draenor's key ley lines. Hmmm... there's where I built my tower, of course. Energy also seems to converge near Karabor. And here, by the throne of elements.\n\nOh very good, we'll be able to put this to use very soon.", objectives = "Complete the legendary shipyard missions until you defeat the Master's Call and acquire a Draenic Sea Chart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39698] = { id = 39698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Rounds", description = "As you can see, we have spared no expense in showing our support of your great quest.\n\nFinal preparations are being made - come, walk with me.", progress = "As soon as preparations are complete, we set out for Stormheim.", completion = "Do you understand the gravity of our task? If we do not fight for our future, we will not have one.", objectives = "Follow Lady Sylvanas Windrunner and prepare her ship to set sail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39699] = { id = 39699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironhorn Leysmithing", description = "I sense great strength in you, yet you refuse to wield it. We Ironhorn use double the metal of any normal blacksmith to craft our wares.\n\nThere is also a technique in how you hammer such quantities of leystone that I will instruct you on.\n\nUse our scrap metal and hammer out the pieces for a gauntlet. I will weld the pieces together when you are finished.", progress = "I'm waiting, outsider.", completion = "Your hammerwork is solid, outsider. You have separated yourself from the chaff.", objectives = "Gather scrap metal around the Ironhorn Enclave. Then use the Greenhoof's Anvil and Forge to craft a Scrapmetal Handguard, a Scrapmetal Palmplate, a Scrapmetal Cuffplate, and 1 Scrapmetal Fingerplates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39702] = { id = 39702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legend of Black Rook Hold", description = "{name}, have you heard of Saris Swifthammer?\n\nHe was a legendary blacksmith amongst the elves of Black Rook Hold. I wonder if any of his research still exists.\n\nI want you to travel there and see if you can discover anything about Saris, or see if he left anything we can research here at my shop.", completion = "Thank you again for freeing me, stranger. I see you wish to discuss the art of blacksmithing.", objectives = "Go to Black Rook Hold and search for Saris Swifthammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39709] = { id = 39709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
