quests[39712] = { id = 39712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistletoe and Stockings" }
quests[39713] = { id = 39713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39714] = { id = 39714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Are the Children?", description = "The children have gone missing!\n\nThat horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them!\n\nOur scouts have spotted him over in Frostfire Ridge.", objectives = "Help save the children.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39715] = { id = 39715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menacing Grumplings", description = "The grumplings are horrid creatures. They're the ones doin' the dirty work for Grumpus.\n\nIf you're able to remove the threat I'm sure rescuing the children won't be much of a problem.", objectives = "Remove the grumpling threat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39716] = { id = 39716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smashing Squashlings", description = "The Bonefleet once raided trading ships traveling the waters of Draenor. One such ship carried farming supplies intended for Elodor.\n\nNow, they use these supplies to sow their plague into our earth. From the putrid mounds sprout vegetative horrors. These abominations must be destroyed, before they can spread across the landscape.", completion = "I bet it felt great to smash those things! Smash, squish, squash!", objectives = "Kill 6 Growing Squashlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39717] = { id = 39717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Mission Complete" }
quests[39718] = { id = 39718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paradise Lost", description = "Archmage Khadgar was planning an expedition to Azsuna - you should seek him out at Krasus' Landing in Dalaran immediately.", completion = "Perfect. Up for a little trip down to Azsuna?", objectives = "Speak with Archmage Khadgar at Krasus' Landing in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39719] = { id = 39719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutiny on the Boneship", description = "Each year, around this time, there is a strange surge of spiritual energy across Draenor. Beckoned by this phenomenon, a ghastly fleet of undead pirates emerges from the mist. We call it the Bonefleet.\n\nThe Bonefleet is led by a savage pirate known as Bonerender. He seeks nothing more than the complete destruction of all of the living of Draenor.\n\nSeek out Bonerender and defeat him, before he sails back into the mist once again.", completion = "Finally, he's returned to the briny deep. I'm sure we'll see him again, but for now let's celebrate!", objectives = "Kill Bonerender.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39720] = { id = 39720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foul Fertilizer", description = "The Bonefleet wants nothing more than to spread their undead curse onto dry land. Like a sickness, it will slowly overtake the landscape if left unchecked.\n\nThe stench of undeath permeates the barrels of fertilizer they use to sow their dread crops. They are the source of the spreading plague, and must be destroyed.", completion = "Thinking what goes into normal fertilizer, I don't even want to know what was in THAT stuff.", objectives = "Destroy 8 kegs of Dread Fertilizer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39721] = { id = 39721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Crew", description = "If we're going to protect Draenor from the Bonefleet menace, we'll need to thin out the crew.\n\nSee to a swift reduction in their numbers, and we might just push them back into the sea for another year.", completion = "We're lucky you were around to take care of those bony brutes!", objectives = "Destroy 12 Boneship crew members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39722] = { id = 39722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging New Strength", description = "Even the most nefarious Legion lords fear your presence on the battlefield. Yet they are relentless, fashioning ever more terrible horrors and fiends in hopes of countering your might.\n\nHighlord, we must augment your power to maintain our edge over the enemy.\n\nThe altar before you holds within it the essence of the countless heroes of the Light buried in these sacred halls. Place your weapon upon the altar and imbue it with new strength.", completion = "I will continue beseeching the Light to bolster the power of your weapon.\n\nFor now, its newfound strength should be more than enough.", objectives = "Imbue your weapon with a new power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39723] = { id = 39723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39724] = { id = 39724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39725] = { id = 39725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39726] = { id = 39726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...And the Anvil", description = "If you truly wish to see my work then you'll have to go and retrieve it as my shop has been raided of everything I've made.\n\nThe breastplates of the Black Rook soldiers were one of my greatest accomplishments. They're light, yet strong and offer great mobility\n\nRelinquish my cursed brethren of their breastplates and bring them back to me. I will explain the finer points of how I made them upon your return.", progress = "Have you acquired any breastplates?", completion = "These pieces will do fine as examples. Now, let me explain how I crafted them...", objectives = "Gather 5 Black Rook Breastplates from the elves of Black Rook Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39727] = { id = 39727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39728] = { id = 39728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39729] = { id = 39729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Knowledge of Black Rook", description = "You have honored me with your help and now I wish to return those favors to you. On that pedestal there is all my research. Take it with you and learn from it so you may carry on my legacy.\n\nThank you again, {name}.", progress = "Were you able to find him?", completion = "This is... this is amazing! There are techniques in here I'd never imagined trying. Good work, {name}!", objectives = "Bring Saris' research back to Alard in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39730] = { id = 39730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Mission Complete" }
quests[39731] = { id = 39731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tranquil Forest", description = "Archmage Khadgar sent word about Val'sharah not long ago. It sounds like he has good news.\n\nYou should meet him on Krasus' Landing in Dalaran as soon as you are able.", completion = "<Archmage Khadgar smiles.>\n\nI rarely get to say this, but I have good news for you, {name}.", objectives = "Speak to Archmage Khadgar on Krasus' Landing in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39732] = { id = 39732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Mission Complete" }
quests[39733] = { id = 39733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lone Mountain", description = "Our sources tell us that a Highmountain tauren emissary has recently arrived in Dalaran. We don't know his intentions, but his people could be an invaluable contact in the region.\n\nKhadgar is greeting the emissary at Krasus' Landing in Dalaran - you should seek him out.", completion = "Greetings champion. I am Warbrave Oro of the Highmountain tauren. I come on the winds of war to find you.", objectives = "Speak to Warbrave Oro at Krasus' Landing in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39734] = { id = 39734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Mission Complete" }
quests[39735] = { id = 39735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormheim", description = "Sky Admiral Rogers has sent word for you to meet her in Dalaran.\n\nShe should be waiting for you in the Violet Citadel. It sounded important.", completion = "It's an honor, {name}.", objectives = "Speak to Sky Admiral Rogers at the Violet Citadel in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39736] = { id = 39736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
