quests[39741] = { id = 39741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Our Ranks", description = "I feel that we should quickly welcome Akama into our ranks. It's important that the others see him treated as one of us, rather than as an outsider.\n\nKor'vas Bloodthorn has proven herself invaluable, time and time again. Her skills in combat are unquestioned and unparalleled. You will find no champion better suited to destroying our enemies.\n\nIt is time to officially raise them up as champions.", completion = "Up until now, the Illidari have been a fairly exclusive club. Demon hunters only. But, as you have so clearly demonstrated, my dear, if we are to move forward trusting one-another, then bringing Akama in is an important step.\n\nIt gives one hope.\n\nAnd, of course, making Kor'vas one of your champions is the obvious choice. No one fights as well as she does.\n\nWhat's that?", objectives = "Recruit Akama and Kor'vas Bloodthorn as your champions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39742] = { id = 39742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Wardens" }
quests[39743] = { id = 39743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valhallas Heroic Reward Quest" }
quests[39744] = { id = 39744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valhallas Reward Quest" }
quests[39745] = { id = 39745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar Teleport" }
quests[39746] = { id = 39746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ring Unbroken", description = "Our defeat at the Broken Shore was decisive. The Burning Legion has a foothold on Azeroth, and the best of our armies are retreating in tatters.\n\nThe elders of the Earthen Ring have called an emergency council near the heart of our world - the Maelstrom. {name}, your triumphs throughout Azeroth and Draenor are the stuff of legend. We need you more than ever.\n\nJoin me at the Maelstrom. Stormcaller Mylra will be flying there shortly - find her at Krasus' Landing here in Dalaran.", completion = "Thank you, {name}. You saved me. You saved us all.\n\nI was... outmatched. My relationship with the elements has changed since the events on Draenor. I have some soul-searching to do. {name}, you must carry the Earthen Ring forward without me. You are the leader they need.", objectives = "Aid the shaman of the Earthen Ring at the Maelstrom. Stormcaller Mylra will fly you there from Krasus' Landing in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39748] = { id = 39748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
