quests[39753] = { id = 39753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39756] = { id = 39756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sound Plan", description = "The Legion still believes us crippled from the Broken Shore. They think we are unable to fight back.\n\nLet's prove them wrong.\n\nWe've been hard at work mapping out the Broken Isles, learning everything we can about each region for our imminent assault.\n\nOnce you've had a chance to peruse the map, you should leave for Dalaran at once and charge into the maw of the beast.\n\nWe will end this madness for good. Light help us all.", completion = "Good luck out there! We're all in this together.", objectives = "Select your first assault point on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39757] = { id = 39757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping Your Edge", description = "Greetings, Deathlord. The blades you hold, while magnificent, have much untapped potential. As you harvest the souls of your enemies their power will continue to grow.\n\nGrand Master Corvus has studied new techniques that may be of use to you, <my lord/my lady>.\n\nYou can find him working the forges on the upper level.", completion = "Ah this weapon is amazing! Do you see the souls of the damned dancing along its edge? Oh how they scream for release!\n\nYes... in their forms I can see how the blade must be shaped.", objectives = "Speak with Grand Master Siegesmith Corvus in Acherus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39758] = { id = 39758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festive Fighters Active" }
quests[39759] = { id = 39759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creepy Crawlers Active" }
quests[39761] = { id = 39761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advanced Runecarving", description = "I've been working for many years to improve the forges. This weapon will be the perfect demonstration of the Soul Forge, their latest design!\n\nWe can take your artifact to the forge and shape it to make use of the power it contains, provided you've fed your weapon enough souls first. Let's give it a little try, eh?", completion = "Oh yes... that will do nicely!\n\nReturn after you've fed your blade another feast of souls and we will make it the most powerful weapon that's ever existed!", objectives = "Use the Soul Forge to empower your Artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39762] = { id = 39762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feltotem Warlock" }
quests[39763] = { id = 39763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Whom the Fel Tolls", description = "<Matthew eyes you up and down, growling slightly>\n\nYou wish me to help you understand this rock? First you do something for me.\n\nThe legion has brought many of its fel machines to conquer this world. Those machines are powered by cores filled with fel energy. And those cores are carried by the lowliest of their minions for distribution.\n\nBring me some cores and I'll give you the information you need.", progress = "Have you acquired what I requested?", completion = "<Matthew lets out a gleeful howl>\n\nImpressive.", objectives = "Obtain 10 Fel Energy Cores from Wyrmtongue Minions in Suramar. Bring them back to Matthew in Dalaran when you are finished.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39764] = { id = 39764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shiny, But Deadly", description = "Soulkeeper Uriah and I were transporting demon prisoners to Allari in Azsuna when our caravan was attacked by kobolds.\n\nThose mindless vermin made off with the soul chambers that house our demonic captives.\n\nThe crystals may be shiny, but they're also deadly. If they are damaged in any way, the demons trapped within may escape.\n\nHead into the cave nearby and recover the soul chambers before it's too late.", progress = "Have you recovered the soul chambers yet?", completion = "Is this all you could find?\n\nWhile I'm grateful to have these gems in my possession once again, it seems that there are still a few missing. I fear they've been broken, which means the demons within have escaped.", objectives = "Collect Soul Chambers from kobolds within Mucksnout Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39765] = { id = 39765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wax On, Wax Off", description = "I've been dead for centuries without having my grave so disturbed... The leader of the local kobolds has stolen my skull from my grave and wears it upon his head!\n\nHe's down in the cave below, but a gate blocks your path from retrieving it directly. Kobolds know their leadership by the skulls they wear, and they are unintelligent enough to believe you their leader if you have one yourself.\n\nKill one of their Skullcaptains and recover his Skull of Bossing Around, and they may let you into the cave.", progress = "The desecration...", completion = "This will work perfectly, I believe.", objectives = "Recover the Skull of Bossing Around from the Bluewax Skullcaptain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39766] = { id = 39766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Worm" }
quests[39767] = { id = 39767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleigh and Snowfighters" }
quests[39768] = { id = 39768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candle to the Grave", description = "These kobolds are taking advantage of the attacks against the Skyhorn tribe. They disturb our graves and steal anything they can get their paws on.\n\nI can do nothing to stop them! Please rid this sacred burial ground of the kobold.", completion = "Some of them seem to be digging less enthusiastically, at the very least.", objectives = "Slay 7 Bluewax Graverobbers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39769] = { id = 39769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gates of Wax", description = "Go talk to the Bluewax Gatekeeper and see if he will let you through to the Candleking. If you can get through by donning the skull, the smell will be worth it.", completion = "What you want, stinky?", objectives = "Speak with the Bluewax Gatekeeper and see if he will let you in to meet the Candleking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39771] = { id = 39771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of Thunder", description = "The White Tiger has prepared a series of challenges for everyone who wants to possess the weapons of the storm.\n\nNow you know of their power - these are the very artifacts that Ra-den himself wielded during the age of the Titans.\n\nCome! I have led arena teams to victory across three continents. With me in your corner, you cannot lose!", progress = "We have trained our whole lives for this, {name}. We cannot fail.", completion = "You really are the chosen one, {name}. I will gladly lay down my life for you.\n\nWherever you take the Earthen Ring, I will follow!", objectives = "Travel to the Temple of the White Tiger and prove yourself worthy to wield the weapons of storm!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39772] = { id = 39772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Hold a Candle To You", description = "Okay guess you can go say hi to Candleking now.", progress = "Have you found my skull?", completion = "Thank the spirits! These kobolds do not honor their ancestors in the way we do. I can rest peacefully now.", objectives = "Recover Oenia's Skull from the Candleking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39773] = { id = 39773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soulkeeper's Fate", description = "Soulkeeper Uriah was injured in the kobold attack, but insisted on venturing further into the cave to recover the stolen soul shards. He told me to wait here with our remaining supplies until he returned, but I fear the worst.\n\nPlease find Uriah. He is the only one who knows how to trap the demons.", completion = "Uriah would not want me to waste time with tears. My mourning can wait until the escaped demons are trapped once again.", objectives = "Find Soulkeeper Uriah within Mucksnout Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39774] = { id = 39774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Detainment", description = "The demons that escaped must be detained. Killing them is not an option. Uriah was entrusted to deliver the prisoners to Allari for interrogation, and I will not let him fail.\n\nI've seen Uriah trap many demons. It seems... complicated, but I think I can pull it off. I'll just need you to subdue them first.", progress = "You must weaken the demons so I am able to trap them.", completion = "Thank you for you help, {name}. I will honor Uriah's memory by completing our journey to Azsuna and delivering the demon prisoners to Allari as planned.", objectives = "Weaken demons so Apprentice Rosalyn can trap them within a soul chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39775] = { id = 39775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormforged Grapple Launcher", sourceObjective = "This looks like one of the grapple launchers the local vrykul use to scale the steep ridges in Stormheim.\n\nThis could come in handy.", sourceObjectiveStatus = "unverified-source-field" }
quests[39776] = { id = 39776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Worms", description = "Snowmane Village behind us was caught completely off guard by the scale of this attack. I will hold the drogbar line here so the civilians have time to prepare their evacuation.\n\nThe drogbar are using worms to burrow their way to the surface and deploy their troops.\n\nI am giving you command of our forces. Use them to slay these worms and cut off enemy reinforcements.", progress = "Worms. Why did it have to be worms? I hate worms.", completion = "That should slow these invaders down.", objectives = "Slay Naxa, Arxas, and Xist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39777] = { id = 39777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy Us Time", description = "We need time to evacuate Snowmane Village. Can you take the fight to these Mightstone drogbar and cull their numbers?\n\nI will direct my healers to get everyone that is unable to fight to safety.", progress = "We need all the time you can buy us.", completion = "Excellent. Thank you, Champion.\n\nWe have managed to get the children and the wounded to safety thanks to your efforts.", objectives = "Slay 10 Mightstone drogbar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39780] = { id = 39780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Underking", description = "Mayla already chased the Underking into his cave. That is something we tell our children never to do.\n\nReckless child, but hey, who wants to live forever? Let us join her in battle.", completion = "Dargrul is just postponing the inevitable.", objectives = "Assault Dargrul the Underking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39781] = { id = 39781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: Death to the Underking", description = "I will direct my people to clear a path through this rubble and assault Dargrul's forces directly.\n\nIt will be a ruse.\n\nNavarrogg proposed a plan that I believe has merit. He knows of a side entrance that might lead directly to Dargrul.\n\nMuster what allies of yours you can and strike at them through this side passage. Recover the Hammer of Khaz'goroth before that villain brings the mountain down on top of us.\n\nWe will provide the distraction you need to get a shot.", progress = "The war continues.", completion = "It was a hard fight, but necessary. {name}, on behalf of the Rivermane, the Skyhorn, the Stonedark, I thank you for your efforts.\n\nBut where one battle ends, another begins. When you stand against the coming of the Burning Legion, know that the tribes of Highmountain stand with you.", objectives = "Recover the Hammer of Khaz'goroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39782] = { id = 39782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exiled Shaman" }
quests[39783] = { id = 39783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet - Terky" }
quests[39784] = { id = 39784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster Pao'lek" }
quests[39786] = { id = 39786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stone Cold Gamble", description = "The second target is a basilisk called Stonefang that lives off the bank of the nearby river. \n\nI put a bigger wager on him, so if you can take him out I'll make sure you get a cut.\n\nI'll need his jaw to verify the kill. Hurry, before those tauren get him first!", progress = "Did you take him out?", completion = "Well, well. I half expected to find your statue on the riverbank. You're gonna get a nice payout once those tauren get back...\n\nYou haven't seen them around, have you?", objectives = "Collect Stonefang's Jaw from Stonefang in Stonescar Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39787] = { id = 39787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rigging the Wager", description = "Care to help settle a bet, chum?\n\nThose tauren are Skyhorn, and they fancy themselves big-time hunters. I bet them a pretty penny that they wouldn't be able to take out some of the biggest beasts in Stormheim.\n\nIf you take em out before they do, I'll split the wager. Deal?\n\nThe first is a big eagle nesting in the foothills. They call him Spitefeather. You can bait him with some meat, but he's up pretty high, so you'll need a grapple gun to get there. I think there's one of them layin around here...", progress = "You got my trophy yet?", completion = "So you took him out, eh? Those tauren are gonna be so jealous when they get back!  \n\nNaturally, you'll have to wait till the tauren get back and pay their wager before I can give you your cut. But in the meantime, I've got another target for you.", objectives = "Lure down and defeat Spitefeather to collect Spitefeather's Beak in the Stormtorn Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39788] = { id = 39788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runewood's Revenge", description = "The Bonespeakers...they are corrupt... hungry for power.\n\nCut them from my woods...", progress = "Has the corruption been removed?", completion = "The Runewood will know peace once more with these Bonespeakers removed from the land. \n\nIt is a good beginning.", objectives = "Kill 8 Bonespeaker Runeaxes and 8 Bonespeaker Carvers in the Runewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39789] = { id = 39789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eating Into Our Business", description = "Greetings traveler! You are welcome to rest at our camp, but if you plan on sticking around a while, I have a proposition for you.\n\nAs you can see, the land here has been very good to us, providing a great natural bounty. Lately, however, the worg have become problematic, and are thinning the herds to unacceptable levels.\n\nI can't take care of them all, so I will offer a bounty for every worg slain in the mesa. Return to me when you have culled their pack a bit.", completion = "Oh, hey! You must be lookin for them tauren was camped here. They just stepped out for a bit, but Snaggle here and I - we can take care of ya!\n\nYou say they were gonna pay you for killin' some worgs, huh? No prob, bub!\n\nI ain't got a lot of gold, but these goods are pretty valuable. Take your pick!", objectives = "Kill 10 Duskpelt worg in Amberfall Mesa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39790] = { id = 39790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernal Brimstone Theory", description = "I've gone through all the research ye gathered for me and I've come up with a theory. As we know, the ore in this world develops over time, through pressure and environmental changes.\n\nBut the Infernal Brimstone ye gave me had its growth accelerated through demonic magic, much like the saronite of Icecrown.\n\nIf we're wantin' to test this out, we'll have to get the help of some magic-users.\n\nTake this brimstone back and go see Matthew Rabis. He may know how to breathe life into it.", completion = "<Sniff sniff> I smell something...fel.", objectives = "Take the brimstone sample to Matthew Rabis in the Underbelly.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39791] = { id = 39791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lay Them to Rest", description = "I would ask a favor, outsider.\n\nAs you step through the graves of ancient heroes, you will no doubt come across spirits of the restless dead, agitated by the Bonespeakers misdeeds. They must be returned to the earth where they are buried, so that they may be judged as well.\n\nTake this bough - it carries with it the essence of the Runewood. Channel its power into a weakened spirit, and it will return to rest.", completion = "I see you carry a branch of the Runewood. Then it was you who laid the spirits to rest? \n\nThough I do not know your purpose, outsider, I appreciate what you have done for our people.", objectives = "Use the Branch of the Runewood to send 8 weakened Restless Ancestors back to the earth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39792] = { id = 39792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stack of Racks", description = "So while we're waiting here, maybe you could fetch us up some grub. Them tauren were runnin low on meats, so I'm sure they'd be thankful to have more.\n\nI hear that musken ribs are the specialty here.  The wild musken here are too lean for any good meat, but across the river there are some nice fat ones. Maybe you should check those out!\n\nDon't worry, I'm pretty sure there aren't any dragons over there...", progress = "Aint nothin like some good old meaty musken ribs, eh pal?", completion = "Oh hey, it's... you again! Of course you didn't have any trouble with those musken. You're a big, tough hero after all!\n\nThe tauren still aren't back, though. I'm a bit worried that they may have gone off and hunted a bit more that they can chew.\n\nOh, I'll take those ribs, though. What do you want for em?", objectives = "Collect 8 Meaty Racks of Musken Ribs from Stout Highland Runehorns in Jotunnwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39793] = { id = 39793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only the Finest", description = "Say, you're a pretty good hunter, eh? Maybe you could help these tauren out by stocking them with some rare furs. I'm sure they'd appreciate it when they got back!\n\nI hear that Stormheim goat hair can be woven into all kinds of things. The rarest are from the silver-tail goats. I think I saw some in that mountain over there.\n\nWhy don't you go and fetch some? I'm sure them tauren would pay you handsomely!", progress = "Make sure to get the good stuff!", completion = "You're back? \n\nI mean... hey, you're back!\n\nWell, the tauren haven't come back yet, but no worries, I'll take that stuff off your hands! Let me show you some of my prime trade goods.", objectives = "Collect 18 Patches of Fine Goat Hair from Silvertail Mountain Goats in Nastrondir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39794] = { id = 39794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Maxwell Tyrosus Slotted" }
quests[39795] = { id = 39795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindicator Boros Slotted" }
quests[39796] = { id = 39796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Haustvald", description = "Your next steps are clear, your feet know the way. Follow them to Haustvald and meet your fate!\n\nIt is the tree you seek, the heart of the mystic Runewood. He will offer guidance, and probably leaves.", completion = "Bound... twisted... \n\nThe Bonespeakers...", objectives = "Meet with Vydhar in the Runewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39797] = { id = 39797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aponi Brightmane Slotted" }
quests[39798] = { id = 39798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Liadrin Slotted" }
quests[39799] = { id = 39799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Next Move", description = "Have you seen the fog that surrounds us? The chill winds of Acherus have provided us with a perfect concealment from the prying eyes of the Legion!\n\nUnder cover of this fog we've been able to send out scouting teams who've put together a fairly comprehensive map of the Broken Isles.\n\nChoose where we shall begin our assault. You, of course, shall have the honor of spearheading our efforts, but the rest of the Ebon Blade will follow your lead.", completion = "A fine choice, Deathlord.", objectives = "Select your order's first assault point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39800] = { id = 39800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greymane's Gambit", description = "The Skyfire is prepared to make way to Stormheim. Should we become engaged, I will require my best fighters on the front line.\n\nThis includes you, {class}.", completion = "It seems you were spared the brunt of the explosion. If only Greymane were so lucky...\n\nOn your feet! We had better get a move on before the Forsaken are on top of us!", objectives = "Complete Greymane's mission aboard the Skyfire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39801] = { id = 39801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Splintered Fleet", description = "Preparations have been made, and we are ready to set sail.\n\nWe must strike out at once. Do not dally, or you will be left behind.", completion = "Hey, you're alive! I guess Withers isn't as crazy as I thought.\n\nIt's a miracle you escaped the Skyfire alive! The pieces of that thing must be scattered all over these mountains after that explosion!", objectives = "Complete Sylvanas' mission to bring the fleet to Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39802] = { id = 39802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hartli the Snatcher" }
quests[39803] = { id = 39803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trials Continue", description = "<Havi's voice continues in your head as the raven stares on>\n\nIf valor you seek, then to the bones you must speak! \n\nBut first you must prepare!", completion = "Ah, the hero of the hour! We must waste no time! \n\nOur business at hand is most important if you wish to succeed in your trials!", objectives = "Meet with Havi in Valdisdall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39804] = { id = 39804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking of Bones", description = "The Trial of Valor will be your next test, and test you it will!\n\nBut only a fool fights on an empty stomach. Are you a fool, outsider?\n\nNo? Then lend these old bones a hand and butcher the moose for our meal. I will spin you a tale of rocks, trees and spirits.", completion = "A fine cut, I must say. \n\nYes, you will do well against the Bonespeakers, I think.", objectives = "Help Havi butcher the moose and learn about your next trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39805] = { id = 39805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drogbar Spellcaster" }
quests[39806] = { id = 39806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crawshuk the Hungry" }
quests[39807] = { id = 39807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Snowbringer" }
quests[39808] = { id = 39808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sepulcher of the Sky Treasure" }
