quests[39813] = { id = 39813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earthmother's Bounty Treasure" }
quests[39814] = { id = 39814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifespring Cavern Treasure" }
quests[39815] = { id = 39815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvan Falls Treasure" }
quests[39816] = { id = 39816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thassarian", description = "Deathlord, I've found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself.\n\n<Mograine turns and nods to a nearby guard.>\n\nHe should be here momentarily.", completion = "You and I have been through much together, {name}. Now, you stand before me as Deathlord and leader of our order. I could not be more proud!\n\nThe battle against the Burning Legion will be hard fought and filled with peril. You should not embark on this alone, my friend.\n\nI will go wherever you command and I will kill whoever you wish me to kill.", objectives = "Welcome your new knight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39817] = { id = 39817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brimstone's Secret", description = "While you were gathering what I asked of you, I did a little testing on the brimstone. It reacted rather violently when I channeled onto it. Careful casting went into making the creature from whom you took this.\n\nUnless you have a host of demon spell-casters at your disposal, recreating such a creature would be impossible.\n\nThat's all I have to tell you. Go now and leave me before my hunger takes over.", completion = "I see. Well that's at least a little helpful.\n\nWith that information in mind, I believe we can move forward with our investigation into this resource.", objectives = "Tell Mama Diggs what you learned from Matthew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39818] = { id = 39818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nazgrim", description = "Deathlord, I've found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself.\n\n<Mograine turns and nods to a nearby guard.>\n\nHe should be here momentarily.", completion = "These foolish class trainers speak to me as if I have never held an axe before!\n\nThey have nothing to teach that I do not already know. The dark power of undeath flows through my veins and it seeks blood and battle!\n\nLet's waste no more time in this dusty necropolis! Send me to the front so that I may spill the blood of our enemies!", objectives = "Welcome your new knight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39819] = { id = 39819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodhunt Highland Treasure" }
