quests[39829] = { id = 39829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleigh and Guards Shared Criteria" }
quests[39830] = { id = 39830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Citadel: Hellfire and Brimstone", description = "When Khadgar's group stormed Hellfire Citadel, they faced many foes that commanded demons, but none more powerful than Archimonde himself.\n\nPerhaps there's somethin' on his corpse that can answer the final questions of unlocking the mystery of this brimstone.", progress = "Don't go alone, lad. That place is teemin' with demons.", completion = "You actually found something?!\n\n<Mama Diggs thumbs through the codex, a stern look on her face as she reads each page.>\n\nAye, here it is. All the answers are within these pages...", objectives = "Gather a group and storm Hellfire Citadel once more. Defeat Archimonde and recover the Infernal Codex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39832] = { id = 39832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plans and Preparations", description = "Your weapon is stronger than ever, but it will need many more souls in order to reach its true potential.\n\nSiouxsie has been collecting reports from the scouts, she will direct you to our enemies and their screaming souls will empower your weapon further.", completion = "Deathlord, I've prepared a brief report on all we've discovered about this new land.\n\nYou should find it quite interesting.", objectives = "Speak to Siouxsie the Banshee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39837] = { id = 39837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unworthy Task", description = "This place is Helheim, the realm of the unworthy dead. Here, the spirits of the dishonorable spend eternity in an endless futile battle, always seeking glory but never able to attain it.\n\nWe should not be here.\n\nWe must find a way out. I will scout ahead - you should try and release some of these captive spirits here. Perhaps one may have some answers for us.", completion = "Free at last! \n\nThe kvaldir caught me while I was tryin' to put together a plan to sneak past that foul dog, Guarm, and have had me locked up ever since! \n\nI thought surely my fate was sealed.", objectives = "Search among the caged vrykul in Helheim for one who can help your escape.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39838] = { id = 39838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire!", description = "You! Adventurer! Give us a hand! The wagon's caught fire!", progress = "Why are you just staring at me with your mouth hanging open! Give us a hand!", completion = "That was... unexpected. Fel flames? I'd say this warrants further investigation.", objectives = "Use Camille Kleister's Water Buckets to put out the fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39839] = { id = 39839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Dust", description = "Nearly everything in the wagon was obliterated by the fire. All that remains is a small pile of dust.\n\nThe cart belonged to Trader Caelen. Perhaps he knows more about what happened.\n\nAs for the dust - either the inscription trainers or the alchemy trainers might have some insight.", completion = "This powder... I think I know what this is. I had theorized its existence, but...\n\nHey, Vanessa! You'd better come take a look at this.", objectives = "Speak with Trader Caelen, Professor Pallin, and Deucus Valdera about the Mysterious Dust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39840] = { id = 39840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Council's Approval", description = "Those results certainly were disappointing. Calcination is a tricky process, better reserved for alchemists and blacksmiths. Still, I thought we'd get more than a measly TWO GRAINS of obliterum.\n\nFor a more efficient reaction, we'll need a special forge, and to get that...\n\n...we'll need permission from the Council of Six.", progress = "I am intrigued...", completion = "I like the way you think, {race}. I've long tried to convince the council that winning this war against the Legion means occasionally stooping to their level.\n\nThe Kirin Tor could use more mavericks like you.", objectives = "Speak with Khadgar in Dalaran, and ask for permission to build an Obliterum Forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39841] = { id = 39841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends in Low Places", description = "My contact is one Oxana Demonslay. She has declined invitation to Dalaran proper, preferring to stay in the sewers of the Underbelly.\n\nIf there is anybody on this rock that knows how to properly build an Obliterum Forge, it is her.\n\nOh, and watch your back while you're down there, {name}.", completion = "The archmage sent you? Hmph.\n\nWas he afraid to come down and visit me personally? Or is he worried that the sewer water might touch the hem of his robe?", objectives = "Report to Oxana Demonslay in the Underbelly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39842] = { id = 39842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Mage's Trash", description = "I can help you build your forge. I can even supply the metal for it. I do, however, require a few more... difficult-to-acquire components.\n\nI need an alchemical heat source, some sort of insulator, and a calefactor. I'm certain that all of these can be found here in the Underbelly... if the guards are looking the other way.", progress = "Don't let those guards see you. They may be corrupt, but they're vigilant.", completion = "I hope these weren't too much trouble to obtain.", objectives = "Find a vial of Alchemical Flame, a roll of Spellbound Insulation, and a Decommissioned Calefactor.\n\nThese items can only be obtained while the Dalaran Sewer Guards are off duty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39843] = { id = 39843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Muck Stops Here", description = "For my next project - sticking the forge's components to one another - I need a magical adherent. And I've found that the built-up sludge of Dalaran's sewers works perfectly for just that.\n\nIt cakes up on the feet, boots, and slithering bellies of Dalaran's more long-lived residents. Scrape some off and bring it here.", progress = "When you live in a sewer, you have to be ready to improvise.", completion = "Let's not make a big deal out of this. You wanted a forge... I'm making one for you. The ends will justify the means.", objectives = "Obtain 20 vials of Spellsludge.\n\nSpellsludge can be found on the powerful Underbelly creatures that appear while the Dalaran Sewer Guards are on duty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39844] = { id = 39844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cold Hard Coin", description = "I am not interested in gold. Your aboveground currencies have little use down here.\n\nI am, however interested in Sightless Eyes. I will gladly accept some as payment for my services.", progress = "Sightless Eyes, {name}.", completion = "<The demon hunter accepts the coins.>", objectives = "Obtain 100 Sightless Eyes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39845] = { id = 39845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Obliterum Forge", description = "The components of the forge are assembled and, as I understand it, Archmage Karlain has secured a location for us to begin construction: aboveground, near the blacksmith.\n\nCome back and visit sometime, {name}.", progress = "Let's get a move on, {name}. I am needed at the Violet Citadel.", completion = "Look at the horns on that thing. And glowing eyes?\n\nThose demon hunters sure do have a flair for the dramatic, don't they?", objectives = "Finalize the construction of the Obliterum Forge in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39846] = { id = 39846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Dalaran - Treasure 001 - Burnt Cart" }
quests[39847] = { id = 39847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sign This", description = "Ah, a fellow scribe!\n\nYou don't look too dim, so how 'bout you and I work together in an effort to discover what we can about the Broken Isles?\n\n(That's the big mass of islands we're floating over.)\n\nHowever! I never agree to a partnership without getting all the requisite legalities out of the way. Sign this for me and we're in business.", progress = "Did you remember to cross your t's and dot your lower case j's?", completion = "Hey, look at that, you know how to spell your name correctly.\n\nGood job, now we can begin!", objectives = "Sign Professor Pallin's contract.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39848] = { id = 39848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Bargain", description = "It looks like your friend didn't make it. A pity, but we must move on.\n\nYou'll want to plead our case to Helya. She is the ruler here. I would accompany you, but I'm afraid I wouldn't help your case.\n\nMeet me when you are finished. I will see if I can find the whereabouts of my shieldmaidens.", progress = "<The air hangs silent as you approach.>", completion = "<Helya's voice fills the air as you stand>\n\nNobody leaves Helheim without my approval! Entertain me, and I may let you pass.", objectives = "Confront Helya and ask to be freed from Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39849] = { id = 39849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Light the Way", description = "Helya must think her challenge unwinnable. We will show her different.\n\nI am unsure what she did, but Helya has weakened you somehow. I have seen similar effects on my shieldmaidens, and now they are trapped by Helya's minions.\n\nI may know a way, however. The Kvaldir ships carry special lanterns bound to this place to navigate through the fog. It is said that the light of these lanterns can release bonds of the spirit.\n\nThere is a kvaldir ship nearby. See if you can find one there.", progress = "Were you able to secure the lantern?", completion = "This appears to be what we need. \n\nNow, we can prepare for the battle ahead.", objectives = "Collect a Helheim Waylight from Bloodbeard in Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39850] = { id = 39850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sundered", description = "I imagine the power of your weapon will be what allows us to defeat Geir, but right now you are too weak for the confrontation. We must reclaim the missing pieces of your spirit.\n\nHelya must have scattered them throughout her realm to keep them from you. If you can find them, shine the lantern and they should be set free.\n\nBe careful, though. It is unlikely that Helya left your spirit fragments unguarded.", progress = "Have you recovered your power?", completion = "Yes, I can feel your power returned. \n\nHelya will regret the day she challenged one such as you.", objectives = "Find and release the Fragment of Will, Fragment of Might, and Fragment of Valor in Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39851] = { id = 39851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in Death", description = "Our power alone may not be enough to fight the behemoth, Geir. Fortunately, Faljar was kind enough to send our allies into Helheim with us.\n\nEarlier, I had discovered several of them being tortured by the elemental forces of Helheim. You may think the dead can't drown, but with Helya's power, this is not the case. \n\nI could not release them then, but now that you possess the waylight, you may be able to.\n\nSeek them out and free them from an eternity of suffering!", progress = "Once unbound, my Valkyra will throttle these wretched minions.", completion = "It is good to have my shieldmaidens returned to my side. \n\nYou have gained allies today, but know you have also gained my gratitude.", objectives = "Release 8 Drowning Valkyra in Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39853] = { id = 39853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory is Eternal", description = "There is no more cause for hesitation. Now is the time to strike.\n\nWe will defeat this foul behemoth and meet Helya's bargain. The path out of Helheim awaits, outsider. \n\nPrepare yourself.", progress = "Together, we can defeat this foe!", completion = "The day is won. Now, we must collect our reward. \n\nLet us hope that Helya keeps her side of the bargain.", objectives = "Defeat Geir in the Eternal Battlefield in Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39854] = { id = 39854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse of the Sea", objectives = "Free cursed vyrkul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39855] = { id = 39855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paid in Lifeblood", description = "We have fulfilled Helya's bargain. Now, we see if she will keep to her word.\n\nWhen you are ready, we should proceed to the throne. If you have any other business here, I would suggest finishing it now.\n\nI will follow your lead, outsider.", completion = "So the dead return from Helheim and back? An impressive feat. \n\nYour worth has been judged and the trial passed. \n\nNow, to your destiny. To the Halls of Valor!", objectives = "Confront Helya and leave Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39856] = { id = 39856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Wraithtalon" }
quests[39857] = { id = 39857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Nemesis", description = "<Helya's voice echoes in the sky above the altar>\n\nYou say that you do not belong here among the unworthy, outsider, but your spirit fragments so easily. How am I to know you speak the truth? \n\nI cannot, so you must show me.\n\nBring yourself to the eternal battlefield and face my champion. If you manage to defeat him, then I may grant you a pardon.", completion = "You do not look good. \n\nI take it Helya did not prove lenient?", objectives = "Return to Ashildir and inform her of Helya's challenge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39858] = { id = 39858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Dreadbog" }
quests[39859] = { id = 39859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Note-Eating Goats", description = "I've followed Hemet on all his expeditions from Stranglethorn to Nagrand to... Nagrand again, taking notes on his grand adventures and turning them into timeless literary tales.\n\nBut my heart is really in the hunt. I want nothing more than to put down the pen, and pick up a rifle!\n\nHemet promised to teach me how to hunt once I finish his latest novel, but the goats around here ate my first draft!\n\nI have no hope of becoming a hunter if my manuscript isn't recovered.", progress = "I've been waitin' all day for Addie to finish her first draft.\n\nHow hard can it be to write a few words about the greatest hunter who's ever lived?", completion = "I've been eager to get my hands on this manuscript! I was startin' to think the gnome had writer's block.", objectives = "Recover Addie's manuscript from Sated Hillstriders within Pinerock Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39860] = { id = 39860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Blood", description = "Oakin Ironbull vouches for you. He's capable, for a Rivermane. You also brought with you proof of your own strength, albeit rather inconclusive proof.\n\nBefore we allow you to move freely within our territory, you must complete the Rite of Blood, which you have already begun. If you succeed--and I doubt you will--talk to me.\n\nEnter the depths of the cave. Defeat whatever foe appears and return to me.", progress = "Are you afraid of the dark?", completion = "Thank you for saving me. I hope now we can trust each other. We must if we are to defeat these Feltotem.", objectives = "Complete the Rite of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39861] = { id = 39861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tying Up Loose Ends", description = "Malfurion Stormrage managed to make landfall in Val'sharah and has already taken care of things there. It seems our fortune is finally turning around!\n\nHe's waiting for you as we speak in Lorlathil. Life is so magical when everything goes according to plan.", progress = "Highlord {name}! You couldn't have arrived at a better time.", completion = "Elune-Adore, {name}.", objectives = "Speak to Aludane Whitecloud at Krasus' Landing to secure a flight to Val'sharah. Speak to Malfurion Stormrage after you arrive in Lorlathil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39862] = { id = 39862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Siegebrul", description = "Worms do not like battle or the surface. They only go where their master tells them.\n\nSo, when in war, kill the master.\n\nSiegebrul Olgrul is the master of worms for the Mightstone drogbar who attack us from the north.\n\nSlay him.", progress = "Siegbrul Olgrul torments all who serve him. There are evil drogbar, and then there is this foul monster.", completion = "\"Siegebrul.\" Bah!\n\nBefore this war we had no need for such titles.\n\nOlgrul was always just a brute who takes pleasure in the pain of others.", objectives = "Slay Siegebrul Olgrul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39863] = { id = 39863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial By Fel Fire", description = "The substance you hold is something that we call \"obliterum\". We had theorized its existence, but until now, we had never actually been able to produce any.\n\nYou say this came from a fire? Of COURSE! Calefaction! Why hadn't I thought of that sooner?\n\nWe'll need to reproduce these results before we take any further action. I know it's asking a lot, but I'll need you to get me some more high-quality armor, in a variety of styles.", progress = "You needn't spend money on expensive breastplates or robes. Simple bracers will do.", completion = "You have the bracers? Very good, now stand back...", objectives = "Obtain a set of Imbued Silkweave Bracers, Dreadleather Bindings, Gravenscale Armbands, and Demonsteel Armguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39864] = { id = 39864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormheim", description = "Nathanos Blightcaller, Champion of the Banshee Queen herself, sent for you in Dalaran.\n\nHe should be waiting for you in the Violet Citadel. It sounded urgent.", completion = "<Nathanos glances over at you, pausing for a moment before acknowledging your presence.>\n\nYes?", objectives = "Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39865] = { id = 39865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Scarecrow Costume" }
quests[39866] = { id = 39866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scout Harefoot" }
quests[39867] = { id = 39867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Not Lion!", description = "I've hunted many exotic beasts in my day, but I've never seen a lion like the one I encountered while scouting the basin.\n\nThe beast's amber eyes locked on mine, luring me closer. I was helpless to this predator's enchanting gaze. It was only when the lion pounced did the stupor break.\n\nI've told Hemet of this magical beast, but he laughs. I'm not lying, {name}! The lion exists.\n\nIf you find the beast, bring me a trophy of your kill, and I'll reward you handsomely.", progress = "I'll have the last laugh when Hemet sees proof that this magical lion exists!", completion = "So I was right! The lion with the amber eyes did exist.\n\nHere's the gold as promised. This is worth every copper. You can't put a price on proving that you're right!\n\nI'll keep this eye, but I wouldn't want the rest of our prize to go to waste. Let's eat!", objectives = "Collect a hunting trophy from the lion that Ellias claims to have seen in Pinerock Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39868] = { id = 39868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair Heroic Reward Quest" }
quests[39869] = { id = 39869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toll for the Soul", objectives = "Defeat Helya and free the Valarjar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39870] = { id = 39870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Soulthirster" }
quests[39871] = { id = 39871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huntress Ellandryn" }
quests[39872] = { id = 39872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beastly Boxer" }
quests[39873] = { id = 39873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Have a Bad Feeling About This", description = "You have no reason to trust me. My cousins led by Dargrul have gone mad with power.\n\nBut I ask you to investigate something. I have a feeling something terrible is about to befall Highmountain, and that Torok and his Bloodtotem are going to be responsible.\n\nIf you don't believe me, look for yourself at the northern side of Cliff's Edge.", completion = "<The cage is empty. Navarrogg is gone.>", objectives = "Investigate Navarrogg's suspicions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39874] = { id = 39874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Enchanted Evening", description = "Welcome! It's nice to see familiar faces returning to Dalaran. You might remember Ildine, Vanessa, and me from Northrend. \n\nArchmage Starsinger is in charge of the shop, but he's away on Kirin Tor business at the moment. He's a fine fellow... mostly.\n\nYour arrival is fortunate. We've run into a problem that we'd love to solve before the archmage returns. Interested in lending a hand?", completion = "I'm relieved you've come, {name}. We could certainly use another enchanter in the shop at a time like this.", objectives = "Speak to Ildine Sorrowspear inside the enchanting shop in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39875] = { id = 39875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Few", description = "As you can see, {name}, we're hard at work producing enchants for the battle against the Legion. Since you're here, we could really use your help wrapping up one of our orders.\n\nIf you could, acquire some vellums and start enchanting them with Versatility. Here, I'll teach you the formula.", progress = "Almost done enchanting those vellums?", completion = "<You hand Ildine the vellums.>\n\nAnd that's the last of 'em. Thanks, {name}!", objectives = "Create 2 Enchant Ring - Word of Versatility vellums for Ildine. You can acquire vellums from a scribe, or from the Auction House.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39876] = { id = 39876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping the Hunters", description = "Now, while I continue to fill the rest of our orders, I'd really appreciate it if you would deliver these vellums to Jace Darkweaver down in Azsuna.\n\nHe and the other demon hunters have been fighting back the Legion for quite some time and could use this as quickly as possible.\n\nThanks, {name}!", completion = "<Jace takes the crate from you and peers inside.>\n\nThe vellums! They're finally here.", objectives = "Deliver the crate of vellums to Jace Darkweaver in Azsuna.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39877] = { id = 39877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Loop", description = "We could use your help down here, {name}. Some of our hunters would benefit greatly from having those vellums applied to their rings right now.\n\nHere take a few. I'll give the rest to one of my other soldiers to hand out.\n\nMy hunters probably won't stop to let you apply the enchants, so you'll just have to do your enchanting even if they're in the midst of battle.", progress = "There's no time to waste. We need to get these enchantments out to as many of my hunters as possible.", completion = "That will certainly help us keep these demons at bay for much longer. We're in your debt, {name}.", objectives = "Use the enchanting vellums on 6 Demon Hunters at the Illidari Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39878] = { id = 39878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Struck", description = "I've made contact with a potential source of new enchantments down in Highmountain. The tauren of Thunder Totem command the spirits to imbue items with great power.\n\nSeek out an enchanter named Twaintail and see if he will share his knowledge with us.\n\nTaurens are known for their sharing... right?", completion = "The spirits told me of your coming, outlander. Let us see if you are indeed the hero this land needs.\n\n<The tauren clears his throat.>\n\nPardon me. I know I come off as a bit dramatic. It's just... well, these things have meaning for me.", objectives = "Speak to Guron Twaintail in Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39879] = { id = 39879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strong Like the Earth", description = "There are many types of spirits in this world, {name}. Some benevolent, some troubled.\n\nThey all resonate with different reagents which we use to enchant our armor. One such reagent are the crystals of the ambershards.\n\nThey are a violent creature born of the earth and have recently been disturbed by the drogbar. However, disturbed or not, the crystals they bear are of great use to my people for enchantments. Bring me some and I'll show you what I mean.", progress = "Crystals aren't the only thing the spirits respond to. There are others, but that is another tale for another time.", completion = "These will do perfectly for my explanation.\n\n<Guron begins to describe the process of speaking to the spirits and how they interact with the crystal.>\n\nI believe you may have come across another type of crystal: the \"leylight shard\". That crystal works similarly, but resonates with different spirits.", objectives = "Defeat Enraged Ambershards and collect \n8 of their Ambershard Crystals. Bring them back to Guron in Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39880] = { id = 39880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste Not", description = "While fighting the ambershards for their crystals, you may come across enchanted armor from our fallen braves. The ambershards care not for such things, but our tribe does not believe in letting anything go to waste.\n\nI'd like you to retrieve our braves' armor and disenchant them into the components from which they were imbued.\n\nBring me back the reagents so my tribe may use them to enchant new armor.", progress = "To waste what we are given, is to laugh at the spirits who gave it to us to begin with.", completion = "You honor our tribe with your deeds. I will see that this dust goes to good use.", objectives = "Go to the Crystal Fissure and search for discarded armor. Disenchant the armor and bring back 15 Thunder Dust to Guron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39881] = { id = 39881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fey Enchantments", description = "The new dusts and crystals we've found in these lands are fascinating, as I'm sure you've already surmised. I'm positive we can expand their usefulness to more of our armor.\n\nI'd like you to go back out into the field and talk to a dryad in Val'sharah. Apparently she may be able to clue us into some enchantments for shoulder pieces.\n\nHer name is Nalamya. You'll find her near the Temple of Elune.", completion = "What is it you want, {race}?\n\n\n\nOh, I see now. You're an enchanter.\n\nI warn you though, if you take my enchantments like those foul elves of Black Rook and use them for evil, you shall feel my wrath one way or another.", objectives = "Seek out Nalamya near the Temple of Elune in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39882] = { id = 39882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket: The Glamour Has Faded", description = "I once taught the night elves how to enchant their armor to strengthen themselves against the evils of this land. One elf in particular garnered my favor.\n\nArch-Druid Glaidalis is his name. He now resides in the forest known as the Darkheart Thicket, plotting to undo this world with this awful blight.\n\nBefore his betrayal, I gave him my book of enchantments to study. I would very much like it back.\n\nI trust you with this task, enchanter. Bring my book back to me.", progress = "If you're truly a friend in this war, then be my sword and strike down Glaidalis.", completion = "You found it? I trust Glaidalis fell in the process?\n\nWhile I feel relieved such a powerful foe has been defeated, I can't help but feel sad for what could have been...\n\nRegardless, you've proven yourself an ally. As a reward, I will teach you one of my enchantments.", objectives = "Kill Arch-Druid Glaidalis in the Darkheart Thicket and recover Nalamya's Book of Enchantments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39883] = { id = 39883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloaked in Tradition", description = "You have seen the ways of the tauren of Thunder Totem... speaking with the spirits, gathering from the land, and letting nothing go to waste. These are potent forces crucial to your quest to aid the Broken Isles.\n\nHere, take this journal back to your enchanter friend. It contains the lessons I have imparted unto you.\n\nPerhaps it will serve to help the greater cause of defeating the Legion.", progress = "Welcome back, {name}. Did you make contact with the tauren?", completion = "I see you brought back a gift from Highmountain.\n\n<Nalthanis thumbs through the pages.>\n\nThis is fascinating! Look here, {name}, some formulas for cloak enchantments. I believe these would come in handy for us at this point in time.", objectives = "Take Guron's Journal to Nalthanis in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39884] = { id = 39884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Longer Worthy", description = "The elves of Black Rook Hold have decided to turn their backs on us. They stay inside their keep, attacking any outsider who dare try to enter.\n\nSuch behavior is intolerable... especially after all the help they've received from my folk and the others of this land.\n\nI want you to do me a favor, {name}. Take their enchanted sigils and reduce them to dust. Bring me back the dust as proof of your deeds.", progress = "Their behavior was so odd and sudden. It makes no sense why they'd turn their backs on us. Still, it's inexcusable.", completion = "<Nalamya takes the dust from you.>\n\nWell done, {race}.", objectives = "Kill night elves within the grounds of Black Rook Hold and collect their Enchanted Raven Sigils. Disenchant the sigils and bring back 8 Raven Dust to Nalamya as proof of their defeat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39889] = { id = 39889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Led Astray", description = "The night elves are no fools, but the elves of Black Rook follow their commanders with blind loyalty. I've no doubt that the blame for their apathy rests heavily upon their commanders.\n\nI know of two of their leaders, who as we speak continue to command their troops to do nothing against the blight encroaching upon my home.\n\nGo to Black Rook Hold and slay Trelan Shieldbreaker and Starlys Strongbow. Let them be an example for those who can help, but wish to remain cowardly.", completion = "Don't worry about proving what you've done for me. I have my own eyes and ears to tell me of your deeds.", objectives = "Go to Black Rook Hold in Val'sharah and slay Trelan Shieldbreaker and Starlys Strongbow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39891] = { id = 39891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed, But Convenient", description = "I need you to return to Azsuna at once, {name}. I've only just heard of an enchantress within the Crumbled Palace who knows of many rare enchantments.\n\nGo to her and see what you can learn at once.", completion = "Ah, a fellow enchanter. Come to earn the marks of my subordinates, have you?\n\nIf that's the case, then you may speak with my sentinel and druid. Earn their trust and they'll grant you their marks.\n\nI, however, have a different task for you...", objectives = "Find Enchantress Ilanya at the Crumbled Palace in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39903] = { id = 39903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Enchanting Home", description = "The more I learn about the Broken Isles, the more convinced I am that it is a land of wonders!\n\nIldine and I were just discussing rumors of a dwelling in Stormheim that was once the home to a vrykul enchantress called Tigrid. It is said the site is perfectly preserved, and her enchantments were so potent that they persist to this day!\n\nInvestigating the home might uncover valuable knowledge, {name}.", completion = "So, {race}, you have discovered my home... all that is left of me.\n\nNot even enough to sustain my beloved enchantments...", objectives = "Investigate Tigrid's home in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39904] = { id = 39904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: Revenge of the Enchantress", description = "For many centuries, even after death, I was capable of weaving enduring enchantments. But since the theft of my enchanting rod by a greedy king, I can barely sustain the little magic I have left.\n\nIf you can recover my enchanting rod from the god-king's ghost, I will reward you in kind.", progress = "The rod is an extension of me, and I of it. It would be nice to hold it once more.", completion = "You have brought back to me my most prized possession. For this I will grant you a bit of my knowledge.\n\nShould you wish to learn more, you only need bring me a few, small components.", objectives = "Retrieve Tigrid's Enchanting Rod from the Halls of Valor and return it to her in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
